        out[f'diff{scale}_robin{leak}']=sparse.csc_matrix(mat)
    for name,sc in [('dirichlet',1e5),('identity',1.)]:
        mat=ref.copy(); mat[[0,-1]]=0; mat[0,0]=mat[-1,-1]=sc; out[name]=sparse.csc_matrix(mat)
    return out

